from pathlib import Path

PAPER_GAP_PREFIX = "docs/paper-gaps/"
EXCLUDED_NOTE_NAMES = {
    "command.tex",
    "policy.tex",
    "proof-gap-protocol.tex",
    "template.tex",
}

